import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;

import java.util.HashMap;

import tk.woppo.sunday.dao.WeatherDataHelper;
import tk.woppo.sunday.dao.WeatherTodayDataHelper;

/**
 * Created by Ho on 2014/7/4.
 */
public class WeatherTodayModel extends BaseModel {

    private static final HashMap<String, WeatherTodayModel> CACHE = new HashMap<String, WeatherTodayModel>();

    /** 城市ID */
    @SerializedName("cityid")
    public String id;

    /** 城市名称 */
    @SerializedName("city")
    public String cityName;

    /** 温度 */
    public String temp;

    /** 天气 */
    public String weather;

    /** 风向 */
    @SerializedName("WD")
    public String wind;

    /** 风力 */
    @SerializedName("WS")
    public String ws;

    /** 湿度 */
    @SerializedName("SD")
    public String sd;

    /** 发布时间 */
    public String time;

    private static void addToCache(WeatherTodayModel model) {
        CACHE.put(model.id, model);
    }

    private static WeatherTodayModel getFromCache(String id) {
        return CACHE.get(id);
    }

    public static WeatherTodayModel fromJson(String json) {
        return new Gson().fromJson(json, WeatherTodayModel.class);
    }

    public static WeatherTodayModel fromCursor(Cursor cursor) {
        String id = cursor.getString(cursor.getColumnIndex(WeatherDataHelper.WeatherDBInfo.ID));
        WeatherTodayModel model = getFromCache(id);
        if (model != null) {
            return model;
        }
        model = new Gson().fromJson(cursor.getString(cursor.getColumnIndex(WeatherTodayDataHelper.WeatherTodayDBInfo.JSON)), WeatherTodayModel.class);
        addToCache(model);
        return model;
    }

    public static class WeatherTodayRequestData {
        public WeatherTodayModel weatherinfo;
    }
}

Q:

Page transitions, depending on URL

This code fades each page out, before going to the URL's destination. However, there are some instances where the user doesn't go to a new page, but goes to a PDF in the browser, or it opens the default mail application. On Safari it seems, if you go to an external site (www.twitter.com) and press the back button, the .wrapper is still faded out. (Perhaps a cache thing?)
function fadeAndGo(x) {

        $(x).click(function (e) {
        e.preventDefault();
        var href = this.href;
        $('.wrapper').fadeOut(function(){
            window.location = href;

        });
        // $('.wrapper').delay()fadeIn();
    });
}

fadeAndGo('a');

Is it possible to either:

Fade out, only if the URL does not contain 'PDF, mailto', or is an external link?
Fade in after a certain amount of time (it faded out, but faded back in after a couple of seconds, in case it was a PDF/mailto).

A:

Try this:
function fadeAndGo(x) {
    $(x).click(function (e) {
        e.preventDefault();
        var href = $(this).attr("href");
        if (!/PDF|mailto/gi.test(href)) {
            $('.wrapper').fadeOut(function () {
                window.location = href;
            }).delay(2000).fadeIn();
        } else {
             window.location = href;
        }
    });
}

